 function describe(before,plan,outcome){const old=new Map(before.inventory.map(i=>[i.instanceId,i])),found=new Set([...(before.characterDiscoveries||[]),...before.inventory.map(i=>i.char)]),seen=new Set(found);return outcome.results.map((r,n)=>{const op=plan.operations[n],materials=(op.type==='duplicate'?[op.keepId,op.materialId]:op.ids||[]).map(id=>old.get(id)).filter(Boolean),item=outcome.inventory.find(i=>i.instanceId===r.instanceId),newReadings=r.type==='duplicate'?r.newReadings||(item?.unlockedReadings||[]).filter(v=>!(old.get(r.instanceId)?.unlockedReadings||[old.get(r.instanceId)?.ruby]).includes(v)):[],fresh=r.type!=='duplicate'&&!seen.has(r.char),upgraded=r.type==='synthesis'&&materials.length>0&&r.jis>materials[0].jis;seen.add(r.char);return{...r,item,materials,newReadings,fresh,upgraded,order:n};}).sort((a,b)=>Number(b.fresh)-Number(a.fresh)||Number(b.upgraded)-Number(a.upgraded)||(b.jis||0)-(a.jis||0)||a.order-b.order);}
