 const modal=node('div','editor-overlay hidden');modal.id='modal-synthesis-result';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','synthesis-result-title');modal.innerHTML='<section class="editor-panel synthesis-shell"><div class="editor-title"><h2 id="synthesis-result-title">錬成</h2><button id="btn-synthesis-close" aria-label="錬成の結果を閉じる">閉じる</button></div><div id="synthesis-stage" class="synthesis-stage" aria-hidden="true"><div class="synthesis-ink"><i></i><i></i><i></i></div><span id="synthesis-material-a" class="synthesis-material material-a kanji-font"></span><span id="synthesis-material-b" class="synthesis-material material-b kanji-font"></span><span class="synthesis-gold-ring"></span><span id="synthesis-reveal-char" class="synthesis-reveal-char kanji-font"></span><span id="synthesis-reveal-ruby"></span></div><p id="synthesis-progress" role="status" aria-live="polite"></p><button id="btn-synthesis-skip" class="quiet-action">演出スキップ・結果をまとめて見る</button><div id="synthesis-results" hidden><p id="synthesis-summary"></p><p id="synthesis-result-note" class="inventory-note"></p><p class="inventory-note">新発見・水準アップを先に表示。文字をタップすると詳細を確認できます。</p><div id="synthesis-result-list"></div><button id="btn-synthesis-more" class="inventory-action secondary" hidden>さらに結果を表示</button><button id="btn-synthesis-return" class="inventory-action">錬成に戻る</button></div></section>';document.body.append(modal);$('synthesis-stage').before($('btn-synthesis-skip'));
 function appendResults(){const stop=Math.min(view.entries.length,view.shown+60);for(;view.shown<stop;view.shown++){const r=view.entries[view.shown],card=node('button','synthesis-result-card');card.type='button';card.dataset.fresh=String(r.fresh);card.dataset.upgraded=String(r.upgraded);const glyph=node('strong','kanji-font',r.char),badges=node('span','synthesis-badges',[r.fresh?'新発見':'',r.upgraded?'水準アップ':'',r.type==='recipe'?'組み合わせ錬成':''].filter(Boolean).join('・'));card.append(glyph,badges,node('span','',r.type==='duplicate'?(r.newReadings.length?'ルビ解放：'+r.newReadings.join('／'):'育成経験値を継承'):(r.jis===5?'元素文字':`JIS第${r.jis}水準`)),node('small','',`Lv.${r.level}${r.item?.autoLocked?'・自動ロック済み':''}`));card.onclick=()=>{const item=gameState.inventory.find(i=>i.instanceId===r.instanceId);if(!item){showToast('この文字は現在の所持一覧にありません。');return;}close();openRubyModal(item);};$('synthesis-result-list').append(card);}$('btn-synthesis-more').hidden=view.shown>=view.entries.length;}
 function reveal(sound=true){if(!view||view.revealed)return;clearTimeout(view.timer);view.revealed=true;root.KanjiGameAudio?.stop();if(sound&&!document.hidden)playSound('reveal');$('synthesis-stage').classList.add('is-finished');$('btn-synthesis-skip').hidden=true;$('synthesis-results').hidden=false;$('synthesis-progress').textContent=`${view.entries.length}回の錬成が完了しました。`;$('synthesis-summary').textContent=`新発見 ${view.entries.filter(r=>r.fresh).length}文字・水準アップ ${view.entries.filter(r=>r.upgraded).length}回・ルビ解放 ${view.entries.reduce((n,r)=>n+r.newReadings.length,0)}個`;$('synthesis-result-note').textContent=view.note||'素材の育成経験値を継承しました。結果は保存済みです。';appendResults();if(document.activeElement===$('btn-synthesis-skip'))$('btn-synthesis-return').focus({preventScroll:true});}
 function close(){if(!view)return;root.KanjiGameAudio?.stop();const focus=view.focus;clearTimeout(view.timer);view=null;modal.classList.add('hidden');resumePlayerEngine();if(focus?.isConnected)focus.focus({preventScroll:true});}
 root.presentSynthesis=(before,plan,outcome,options={})=>{if(view)close();const entries=describe(before,plan,outcome);if(!entries.length)return;view={entries,shown:0,revealed:false,note:options.note,focus:document.activeElement};const r=entries[0];pausePlayerOverlay();modal.classList.remove('hidden');modal.querySelector('.synthesis-shell').scrollTop=0;$('synthesis-result-title').textContent=options.title||'錬成の結果';$('synthesis-results').hidden=true;$('synthesis-result-list').replaceChildren();$('btn-synthesis-more').hidden=true;$('btn-synthesis-skip').hidden=false;const stage=$('synthesis-stage');stage.className='synthesis-stage';stage.dataset.upgraded=String(r.upgraded);stage.dataset.duplicate=String(r.type==='duplicate');stage.dataset.bulk=String(entries.length>1);$('synthesis-material-a').textContent=r.materials[0]?.char||'';$('synthesis-material-b').textContent=r.materials[1]?.char||'';$('synthesis-reveal-char').textContent=r.char;$('synthesis-reveal-ruby').textContent=r.newReadings[0]||'';$('synthesis-progress').textContent=entries.length>1?'素材をまとめて錬成しています…':r.type==='duplicate'?'文字に新しい読みが宿ります…':'素材が墨に溶け、新しい文字が生まれます…';void stage.offsetWidth;stage.classList.add('is-playing');playSound('fusion');view.timer=setTimeout(reveal,entries.length>1?1200:2300);$('btn-synthesis-skip').focus({preventScroll:true});if(matchMedia('(prefers-reduced-motion: reduce)').matches)reveal(false);};
 new MutationObserver(()=>{if(view&&modal.classList.contains('hidden'))close();}).observe(modal,{attributes:true,attributeFilter:['class']});
