 $('btn-synthesis-skip').onclick=()=>reveal(false);$('synthesis-stage').onclick=()=>reveal(false);$('btn-synthesis-close').onclick=close;$('btn-synthesis-return').onclick=close;$('btn-synthesis-more').onclick=appendResults;
 modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const list=[...modal.querySelectorAll('button')].filter(b=>!b.hidden&&b.getClientRects().length),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
